let _sharedAudioCtx = null;
function getAudioCtx() {
    if (DEMO)
        return null;
    if (typeof window === 'undefined')
        return null;
    if (!_sharedAudioCtx) {
        const Ctx = window.AudioContext || window.webkitAudioContext;
        if (!Ctx)
            return null;
        _sharedAudioCtx = new Ctx();
    }
    if (_sharedAudioCtx.state === 'suspended')
        _sharedAudioCtx.resume();
    return _sharedAudioCtx;
}
function playTone(freq, duration, type = 'sine', peakGain = 0.06) {
    const ctx = getAudioCtx();
    if (!ctx)
        return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(peakGain, ctx.currentTime + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + duration);
}
// A held, unwavering monitor tone that stays flat until the very end, then cuts off -
// the classic hospital "flatline" sound, rather than a tone that decays the whole time.
function playSustainedTone(freq, duration, peakGain = 0.05) {
    const ctx = getAudioCtx();
    if (!ctx)
        return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(peakGain, ctx.currentTime + 0.03);
    gain.gain.setValueAtTime(peakGain, ctx.currentTime + duration - 0.15);
    gain.gain.linearRampToValueAtTime(0.0001, ctx.currentTime + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + duration);
}
// Filtered white-noise "swipe", a brushing/scrubbing texture, sweeping through a
// bandpass filter so it sounds like a pass of cleaning rather than a flat hiss.
function playSweep(duration, freqFrom, freqTo, peakGain = 0.05) {
    const ctx = getAudioCtx();
    if (!ctx)
        return;
    const bufferSize = Math.floor(ctx.sampleRate * duration);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++)
        data[i] = Math.random() * 2 - 1;
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.Q.value = 1.1;
    filter.frequency.setValueAtTime(freqFrom, ctx.currentTime);
    filter.frequency.exponentialRampToValueAtTime(freqTo, ctx.currentTime + duration);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(peakGain, ctx.currentTime + duration * 0.25);
    gain.gain.linearRampToValueAtTime(0.0001, ctx.currentTime + duration);
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);
    noise.start();
    noise.stop(ctx.currentTime + duration);
}
