    notification: () => { playTone(880, 0.12, 'sine', 0.05); setTimeout(() => playTone(1180, 0.1, 'sine', 0.04), 80); },
    // Gets louder/lower/harsher as phase increases (1=mild, 4=most intense)
    mouldGrowth: (phase = 1) => {
        const p = Math.min(Math.max(phase, 1), 4);
        const gain = 0.04 + p * 0.025;
        const baseFreq = 180 - p * 22;
        playTone(baseFreq, 0.3 + p * 0.08, 'sawtooth', gain);
        setTimeout(() => playTone(baseFreq - 40, 0.35 + p * 0.08, 'sawtooth', gain * 0.85), 120);
        if (p >= 3)
            setTimeout(() => playTone(baseFreq - 70, 0.3, 'square', gain * 0.5), 220);
    },
    // Cleansing, sounds like sweeping/scrubbing passes across the brain,
    // each pass brighter than the last, settling into a clear resolving tone.
    cleansing: () => {
        playSweep(0.5, 300, 1400, 0.06);
        setTimeout(() => playSweep(0.45, 400, 1800, 0.055), 380);
        setTimeout(() => playSweep(0.4, 500, 2200, 0.05), 720);
        setTimeout(() => playTone(880, 0.6, 'sine', 0.045), 950);
        setTimeout(() => playTone(1320, 0.7, 'sine', 0.035), 1080);
    },
